WITH source AS (SELECT mktcode,tgtcode,bizdate,volume,ROW_NUMBER() OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate DESC) AS lookback_row FROM `newzl`.`hsj_stock_hq_basic`), eligible AS (SELECT * FROM source WHERE lookback_row<=10), daily AS (SELECT mktcode,tgtcode,bizdate,MAX(volume) AS value FROM eligible GROUP BY mktcode,tgtcode,bizdate), lagged AS (SELECT mktcode,tgtcode,bizdate,value,LAG(value) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate) AS previous FROM daily), qualified AS (SELECT mktcode,tgtcode FROM lagged GROUP BY mktcode,tgtcode HAVING SUM(CASE WHEN (value-previous)*100/NULLIF(ABS(previous),0)>50 THEN 1 ELSE 0 END)>0) SELECT a.mktcode,a.tgtcode,a.bizdate FROM `newzl`.`hsj_stock_hq_basic` a JOIN qualified q ON q.mktcode=a.mktcode AND q.tgtcode=a.tgtcode WHERE a.bizdate='2026-04-14';
